    blue_shirt_patches = image_patch.find("blue shirt")
    if not blue_shirt_patches:
        return "No blue shirt found in the image."
    blue_shirt_patch = blue_shirt_patches[0]
    person_patches = blue_shirt_patch.find("person")
    if not person_patches:
        return "No person found in the blue shirt."
    person_patch = person_patches[0]
    if person_patch.overlaps_with(0, 0, image_patch.width, image_patch.height):
        return "The person is in the back of the blue shirt."
    return "The person is not in the back of the blue shirt."

def execute_command(image) -> str:
    image_patch = ImagePatch(image)
    right_guy_patches = image_patch.find("right guy")
    if right_guy_patches:
        return right_guy_patches[0].simple_query("What is the color?")
    else:
        return "No right guy found in the image."

def execute_command(image) -> str:
    image_patch = ImagePatch(image)
    guy_patches = image_patch.find("guy")
    if not guy_patches:
        return "No guy found in the image."
    hard_rock_shirt_patches = [patch for patch in guy_patches if patch.verify_property("shirt", "hard rock")]
    if not hard_rock_shirt_patches:
        return "No guy wearing a hard rock shirt found in the image."
    return "A guy wearing a hard rock shirt is found in the image."

