def execute_command(image):
    image_patch = ImagePatch(image)
    guy_patches = image_patch.find("guy")
    if not guy_patches:
        return "No guy found in the image."
    guy_patches.sort(key=lambda patch: patch.compute_depth())
    best_guy_patch = guy_patches[-1]
    if not best_guy_patch.verify_property("guy", "in black shorts"):
        return "The guy is not in black shorts."
    return best_guy_patch.simple_query("What color is the guy's shorts?")

